<?php namespace App\Http\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource; class CatechismClassResource extends JsonResource { public function toArray(Request $r):array{return ['id'=>$this->id,'name'=>$this->name,'code'=>$this->code,'status'=>$this->status,'academic_year'=>$this->whenLoaded('academicYear',fn()=>['id'=>$this->academicYear->id,'name'=>$this->academicYear->name]),'level'=>$this->whenLoaded('level',fn()=>['id'=>$this->level->id,'name'=>$this->level->name]),'classroom'=>$this->whenLoaded('classroom',fn()=>['id'=>$this->classroom?->id,'name'=>$this->classroom?->name]),'children_count'=>$this->when(isset($this->children_count),$this->children_count),'schedules'=>$this->whenLoaded('schedules')];} }
